        if decision_type == DECISION_PICK_POINT:
            if self.cult_ambush_point_dialog is None:
                return
            from ..utility.decision_utils import resolve_decision_command
            from .decision_ui_utils import first_option_id, option_entries, option_id_for_action

            ctx = dict(getattr(request, "context", {}) or {})
            ability_key = str(ctx.get("ability", "") or "").strip().lower()

            title = str(ctx.get("ability_name", "") or getattr(request, "prompt", "") or "Select Point")
            instructions = str(ctx.get("instruction", "") or "Select a point on the battlefield.")
            if ability_key == "subterranean_assault_tunnel_marker_placement":
                instructions = (
                    "Select a Tunnel Marker position within 1\" of the arriving Burrower unit "
                    "and more than 3\" from enemy units."
                )

            def _validate_point(x, y):
                if ability_key == "subterranean_assault_tunnel_marker_placement":
                    unit_id = str(ctx.get("unit_id", "") or "")
                    unit = self._resolve_unit_by_id(unit_id)
                    if unit is None:
                        return {"valid": False, "reason": "Burrower unit not found."}
                    army = unit.get_parent_army() if hasattr(unit, "get_parent_army") else None
                    mgr = getattr(army, "tyranids_detachments", None) if army is not None else None
                    validate_fn = getattr(mgr, "validate_subterranean_assault_tunnel_marker_point", None) if mgr is not None else None
                    if not callable(validate_fn):
                        return {"valid": False, "reason": "Tunnel Marker validation unavailable."}
                    valid, reason = validate_fn(unit=unit, point=(float(x), float(y)), game=self.game)
                    if not bool(valid):
                        return {"valid": False, "reason": str(reason or "Invalid point.")}
                    return {"valid": True, "reason": "OK"}
                if ability_key == "fleet_commander_marker_2":
                    first = ctx.get("first_marker_point")
                    if not isinstance(first, (list, tuple)) or len(first) < 2:
                        return {"valid": False, "reason": "First marker point is unavailable."}
                    try:
                        fx = float(first[0])
                        fy = float(first[1])
                        px = float(x)
                        py = float(y)
                    except (TypeError, ValueError):
                        return {"valid": False, "reason": "Point coordinates must be numeric."}
                    try:
                        marker_range = float(ctx.get("marker_range", 12.0) or 12.0)
                    except (TypeError, ValueError):
                        marker_range = 12.0
                    marker_range = float(max(0.0, marker_range))
                    dx = float(px - fx)
                    dy = float(py - fy)
                    dist = float((dx * dx + dy * dy) ** 0.5)
                    if dist > marker_range + 1e-6:
                        return {
                            "valid": False,
                            "reason": f"Second marker must be within {marker_range:.1f}\" of the first marker.",
                        }
                    return {"valid": True, "reason": "OK"}
                if ability_key == "summon_the_cult_marker_relocation":
                    selected_option_id = ""
                    try:
                        selected_option_id = self.cult_ambush_point_dialog.get_selected_option_id()
                    except Exception:
                        selected_option_id = ""
                    marker_id = ""
                    for entry in list(option_entries(request) or []):
                        if str(entry.get("option_id", "") or "") != str(selected_option_id or ""):
                            continue
                        payload = dict(entry.get("payload", {}) or {})
                        marker_id = str(payload.get("marker_id", "") or "").strip()
                        break
                    if not marker_id:
                        return {"valid": False, "reason": "Select a threatened Cult Ambush marker first."}
                    validate_fn = getattr(self.game, "_validate_summon_the_cult_marker_relocation", None)
                    if not callable(validate_fn):
                        return {"valid": False, "reason": "Summon the Cult validation unavailable."}
                    valid, reason = validate_fn(ctx, marker_id=marker_id, point=(float(x), float(y)))
                    if not bool(valid):
                        return {"valid": False, "reason": str(reason or "Invalid point.")}
                    return {"valid": True, "reason": "OK"}
                if ability_key == "evasive_vanguard_marker_relocation":
                    selected_option_id = ""
                    try:
                        selected_option_id = self.cult_ambush_point_dialog.get_selected_option_id()
                    except Exception:
                        selected_option_id = ""
                    marker_id = ""
                    for entry in list(option_entries(request) or []):
                        if str(entry.get("option_id", "") or "") != str(selected_option_id or ""):
                            continue
                        payload = dict(entry.get("payload", {}) or {})
                        marker_id = str(payload.get("marker_id", "") or "").strip()
                        break
                    if not marker_id:
                        return {"valid": False, "reason": "Select a threatened Cult Ambush marker first."}
                    validate_fn = getattr(self.game, "_validate_evasive_vanguard_marker_relocation", None)
                    if not callable(validate_fn):
                        return {"valid": False, "reason": "Evasive Vanguard validation unavailable."}
                    valid, reason = validate_fn(ctx, marker_id=marker_id, point=(float(x), float(y)))
                    if not bool(valid):
                        return {"valid": False, "reason": str(reason or "Invalid point.")}
                    return {"valid": True, "reason": "OK"}
                if ability_key == "cult_ambush_threatened_marker_relocation":
                    selected_option_id = ""
                    try:
                        selected_option_id = self.cult_ambush_point_dialog.get_selected_option_id()
                    except Exception:
                        selected_option_id = ""
                    marker_id = ""
                    relocation_mode = ""
                    source_unit_id = ""
                    for entry in list(option_entries(request) or []):
                        if str(entry.get("option_id", "") or "") != str(selected_option_id or ""):
                            continue
                        payload = dict(entry.get("payload", {}) or {})
                        marker_id = str(payload.get("marker_id", "") or "").strip()
                        relocation_mode = str(payload.get("relocation_mode", "") or "").strip()
                        source_unit_id = str(payload.get("source_unit_id", "") or "").strip()
                        break
                    if not marker_id:
                        return {"valid": False, "reason": "Select a threatened Cult Ambush marker first."}
                    if not relocation_mode:
                        return {"valid": False, "reason": "Select a relocation mode first."}
                    validate_fn = getattr(self.game, "_validate_cult_ambush_threatened_marker_relocation", None)
                    if not callable(validate_fn):
                        return {"valid": False, "reason": "Threatened marker relocation validation unavailable."}
                    valid, reason = validate_fn(
                        ctx,
                        marker_id=marker_id,
                        relocation_mode=relocation_mode,
                        source_unit_id=source_unit_id,
                        point=(float(x), float(y)),
                    )
                    if not bool(valid):
                        return {"valid": False, "reason": str(reason or "Invalid point.")}
                    return {"valid": True, "reason": "OK"}
                if ability_key == "regimental_reinforcements_marker_placement":
                    validate_fn = getattr(self.game, "_validate_regimental_reinforcements_marker_placement", None)
                    if not callable(validate_fn):
                        return {"valid": False, "reason": "Regimental Reinforcements validation unavailable."}
                    valid, reason = validate_fn(ctx, point=(float(x), float(y)))
                    if not bool(valid):
                        return {"valid": False, "reason": str(reason or "Invalid point.")}
                    return {"valid": True, "reason": "OK"}
                if ability_key == "cult_infiltration_marker_relocation":
                    selected_option_id = ""
                    try:
                        selected_option_id = self.cult_ambush_point_dialog.get_selected_option_id()
                    except Exception:
                        selected_option_id = ""
                    marker_id = ""
                    for entry in list(option_entries(request) or []):
                        if str(entry.get("option_id", "") or "") != str(selected_option_id or ""):
                            continue
                        payload = dict(entry.get("payload", {}) or {})
                        marker_id = str(payload.get("marker_id", "") or "").strip()
                        break
                    if not marker_id:
                        return {"valid": False, "reason": "Select a Cult Ambush marker first."}
                    validate_fn = getattr(self.game, "_validate_cult_infiltration_marker_relocation", None)
                    if not callable(validate_fn):
                        return {"valid": False, "reason": "Cult Infiltration validation unavailable."}
                    valid, reason = validate_fn(ctx, marker_id=marker_id, point=(float(x), float(y)))
                    if not bool(valid):
                        return {"valid": False, "reason": str(reason or "Invalid point.")}
                    return {"valid": True, "reason": "OK"}
                return {"valid": True, "reason": "OK"}

            def _on_confirm(option_id: str, point):
                cmd_result = resolve_decision_command(
                    self.game,
                    request,
                    option_id,
                    result_payload={"point": list(point)},
                    player_id=getattr(player, "id", None),
                )
                if not bool(getattr(cmd_result, "ok", False)):
                    errors = tuple(getattr(cmd_result, "errors", ()) or ())
                    reason = str(errors[0] or "Invalid point.") if errors else "Invalid point."
                    try:
                        self.cult_ambush_point_dialog.set_validation_result(valid=False, reason=reason)
                    except Exception:
                        pass
                    return False
                apply_result = getattr(cmd_result, "value", None)
                if apply_result is not None and not bool(getattr(apply_result, "ok", False)):
                    errors = tuple(getattr(apply_result, "errors", ()) or ())
                    reason = str(errors[0] or "Invalid point.") if errors else "Invalid point."
                    try:
                        self.cult_ambush_point_dialog.set_validation_result(valid=False, reason=reason)
                    except Exception:
                        pass
                    return False
                try:
                    self.cult_ambush_point_dialog.hide()
                except Exception:
                    pass
                return True

            def _on_cancel():
                skip_id = option_id_for_action(request, "skip")
                if skip_id:
                    resolve_decision_command(
                        self.game,
                        request,
                        skip_id,
                        result_payload={"skipped": True},
                        player_id=getattr(player, "id", None),
                    )
                else:
                    default_id = first_option_id(request)
                    if default_id:
                        try:
                            self.cult_ambush_point_dialog.hide()
                        except Exception:
                            pass
                    return
                try:
                    self.cult_ambush_point_dialog.hide()
                except Exception:
                    pass

            self.cult_ambush_point_dialog.show(
                game_view=self,
                title=title,
                instructions=instructions,
                validate_cb=_validate_point,
                on_confirm=_on_confirm,
                on_cancel=_on_cancel,
                decision_request=request,
            )
            try:
                self.dialog_manager.open(self.cult_ambush_point_dialog, modal=True)
            except Exception:
                pass
            return

