    def _miracle_dice_provider(
        self,
        player=None,
        unit=None,
        roll_type: str = "",
        dice_count: int = 1,
        die_faces: int = 6,
        pool: Optional[list[int]] = None,
        **_kwargs,
    ):
        """
        Blocking modal prompt for selecting a Miracle die to substitute.
        Returns the chosen die value, or None to skip.
        """
        try:
            if player is None or not getattr(player, "has_control", lambda: False)():
                return None
        except Exception:
            return None

        values = list(pool or [])
        if not values:
            return None

        try:
            from .dialogs import MiracleDiceDialog
        except Exception:
            return None

        if not hasattr(self, "miracle_dice_dialog") or self.miracle_dice_dialog is None:
            self.miracle_dice_dialog = MiracleDiceDialog(self.screen.get_width(), self.screen.get_height())

        rt = str(roll_type or "").strip().lower()
        title = "Acts of Faith"
        ulabel = getattr(unit, "name", "Unit")
        msg = f"{ulabel} can perform an Act of Faith.\nChoose a Miracle die to substitute for this {rt or 'roll'}."
        try:
            if int(dice_count or 1) > 1:
                msg += f"\nThis replaces 1 of {int(dice_count)} dice."
        except Exception:
            pass
        try:
            needed = _kwargs.get("needed", None)
            if needed is not None:
                msg += f"\nNeed {int(needed)}+."
        except Exception:
            pass

        from ..engine.decision_kinds import DECISION_USE_MIRACLE_DIE
        from ..engine.decisions import DecisionOption, DecisionRequest
        from ..utility.decision_utils import resolve_decision_command
        from ..utility.entity_ids import get_entity_id

        # Show highest values first for clarity
        try:
            values_sorted = sorted(values, reverse=True)
        except Exception:
            values_sorted = values

        unit_id = get_entity_id(unit) if unit is not None else None
        options = [
            DecisionOption.create(str(val), payload={"die_value": int(val), "unit_id": unit_id})
            for val in list(values_sorted or [])
        ]
        options.append(DecisionOption.create("Skip", payload={"action": "skip", "unit_id": unit_id}))
        req_context = {
            "unit_id": unit_id,
            "roll_type": str(roll_type or ""),
            "dice_count": int(dice_count or 1),
            "die_faces": int(die_faces or 6),
            "pool": list(values_sorted or []),
            "ability": "acts_of_faith",
            "ability_name": "Acts of Faith",
        }
        needed = _kwargs.get("needed", None)
        if needed is not None:
            req_context["needed"] = int(needed)
        req = _require_pending_decision_request(self.game if self.game is not None else None,
            DECISION_USE_MIRACLE_DIE,
            "Select Miracle Die",
            player_id=getattr(player, "id", None),
            options=options,
            context=_request_lookup_context(req_context),

        )
        _mark_request_ui_prompted(req, message=msg)

        dlg = self.miracle_dice_dialog
        choice_holder = {"choice": None, "done": False}

        def _on_choice(option_id: str):
            if not option_id:
                choice_holder["choice"] = None
                choice_holder["done"] = True
                return
            selected = None
            for opt in list(getattr(req, "options", []) or []):
                if getattr(opt, "option_id", None) == option_id:
                    selected = opt
                    break
            chosen_val = None
            if selected is not None:
                payload = dict(getattr(selected, "payload", {}) or {})
                if str(payload.get("action", "") or "").lower() == "skip":
                    chosen_val = None
                else:
                    chosen_val = payload.get("die_value", payload.get("value"))
            if self.game is not None:
                resolve_decision_command(
                    self.game,
                    req,
                    option_id,
                    result_payload={},
                    player_id=getattr(player, "id", None),
                )
            try:
                chosen_val = int(chosen_val) if chosen_val is not None else None
            except Exception:
                chosen_val = None
            choice_holder["choice"] = chosen_val
            choice_holder["done"] = True

        dlg.show(
            title=title,
            message=msg,
            dice_values=values_sorted,
            callback=_on_choice,
            skip_label="Skip",
            decision_request=req,
        )
        try:
            self.dialog_manager.open(dlg, modal=True)
        except Exception:
            pass

        clock = pygame.time.Clock()
        while dlg.visible and not choice_holder["done"]:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit()
                    return None
                try:
                    self.dialog_manager.handle_event(event)
                except Exception:
                    pass
            try:
                self.draw()
            except Exception:
                try:
                    dlg.draw(self.screen)
                    pygame.display.update()
                except Exception:
                    pass
            clock.tick(60)

        return choice_holder["choice"]

    def _miracle_dice_pool_reroll_provider(
        self,
        player=None,
        unit=None,
        model=None,
        pool: Optional[list[int]] = None,
        max_rerolls: int = 1,
        reason: str = "",
        **_kwargs,
    ):
        """Blocking prompt for selecting up to N Miracle dice from the pool to re-roll."""
        try:
            if player is None or not getattr(player, "has_control", lambda: False)():
                return None
        except Exception:
            return None
        values = list(pool or [])
        if not values:
            return None
        try:
            limit = max(0, int(max_rerolls or 0))
        except Exception:
            limit = 0
        if limit <= 0:
            return None

        selected_indices: list[int] = []
        working_pool = list(values)
        prompts = min(int(limit), len(working_pool))
        for _ in range(prompts):
            chosen_val = self._miracle_dice_provider(
                player=player,
                unit=unit,
                roll_type=str(reason or "miracle pool re-roll"),
                dice_count=1,
                die_faces=6,
                pool=[v for v in list(working_pool) if v is not None],
            )
            if chosen_val is None:
                break
            picked_index = None
            for idx, val in enumerate(working_pool):
                if val is None:
                    continue
                if int(val) == int(chosen_val):
                    picked_index = idx
                    break
            if picked_index is None:
                continue
            selected_indices.append(int(picked_index))
            working_pool[picked_index] = None

        if not selected_indices:
            return None
        return {"indices": list(selected_indices)}

    # ---------------- Quarry/Victim selection prompts ----------------

    def _queue_quarry_selection_prompts(self, game, *, ability_key: str) -> None:
        if game is None:
            return
        try:
            from ..engine.decision_kinds import DECISION_CHOOSE_QUARRY
        except Exception:
            return
        queue = getattr(game, "decision_queue", None)
        if queue is None or not hasattr(queue, "list"):
            return

        pending_reqs = []
        for req in list(queue.list() or []):
            if str(getattr(req, "decision_type", "")) != DECISION_CHOOSE_QUARRY:
                continue
            ctx = getattr(req, "context", {}) or {}
            if str(ctx.get("ability", "")) != ability_key:
                continue
            pending_reqs.append((req, ctx))

        if not pending_reqs:
            return

        try:
            current = game.get_current_player()
            others = [p for p in list(getattr(game, "players", []) or []) if p is not current]
            order = [current] + others
        except Exception:
            order = list(getattr(game, "players", []) or [])

        pending_unit_ids = set()
        for existing in list(getattr(self, "_pending_quarry_queue", []) or []):
            try:
                pending_unit_ids.add((str(existing[2]), str(get_entity_id(existing[1]))))
            except Exception:
                continue
        active_dialog = getattr(self, "quarry_selection_dialog", None)
        if active_dialog is not None and bool(getattr(active_dialog, "visible", False)):
            active_req = getattr(active_dialog, "decision_request", None)
            active_ctx = dict(getattr(active_req, "context", {}) or {})
            active_ability = str(active_ctx.get("ability", "") or "")
            active_source_id = str(active_ctx.get("source_unit_id", "") or "")
            if active_ability and active_source_id:
                pending_unit_ids.add((active_ability, active_source_id))

        for req, ctx in pending_reqs:
            player = self._resolve_player_by_id(getattr(req, "player_id", None))
            if player is None:
                continue
            try:
                if not player.has_control():
                    continue
            except Exception:
                continue
            unit = self._resolve_unit_by_id(ctx.get("source_unit_id"))
            if unit is None:
                continue
            try:
                uid = str(get_entity_id(unit))
            except Exception:
                uid = None
            key = (str(ability_key), str(uid or ""))
            if uid and key in pending_unit_ids:
                continue
            self._pending_quarry_queue.append((player, unit, str(ability_key)))
            if uid:
                pending_unit_ids.add(key)

        if self._pending_quarry_queue:
            self._open_next_quarry_prompt()

