    def _finalize_overwatch(self, player, name: str, context: Dict[str, Any], shooter_unit) -> None:
        if self._overwatch_flow_active:
            return
        manager = getattr(player, "stratagems", None)
        if manager is None:
            return
        if shooter_unit is None:
            logger.info("Overwatch: no shooter selected")
            return
        ctx = dict(context)
        ctx["shooter_unit"] = shooter_unit
        if "phase_name" not in ctx:
            phase_name = getattr(manager, "_current_phase_name", None)
            if phase_name:
                ctx["phase_name"] = phase_name
        enemy = ctx.get("enemy_unit")
        overwatch_used = bool(getattr(manager, "_used_this_turn", {}).get("OVERWATCH", False))
        can_traitor = False
        can_eye = False
        try:
            can_traitor = bool(getattr(shooter_unit, "can_use_traitor_enforcer_overwatch", lambda _g=None: False)(self.game))
        except Exception:
            can_traitor = False
        try:
            can_eye = bool(
                getattr(shooter_unit, "can_use_eye_of_the_augurium_stratagem_discount", lambda _g=None, stratagem_name="": False)(
                    self.game,
                    stratagem_name="OVERWATCH",
                )
            )
        except Exception:
            can_eye = False
        if overwatch_used and not can_traitor and not can_eye:
            logger.info("Overwatch: already used this turn")
            return

        def _continue_overwatch(use_traitor: bool, use_eye: bool = False):
            try:
                player.set_next_optional_decision("BRUTAL_EXAMPLE_OVERWATCH", bool(use_traitor))
            except Exception:
                pass
            try:
                player.set_next_optional_decision("EYE_OF_THE_AUGURIUM_STRATAGEM_DISCOUNT", bool(use_eye))
            except Exception:
                pass
            if overwatch_used and not use_traitor and not use_eye:
                logger.info("Overwatch: repeat-use ability declined; cannot use Overwatch again this turn")
                return
            if callable(getattr(self, "_request_overwatch_shooting", None)):
                overwatch_threshold = 6
                try:
                    get_threshold = getattr(shooter_unit, "get_destroyer_of_futures_overwatch_hit_threshold", None)
                    if callable(get_threshold):
                        threshold = int(get_threshold(enemy_unit=enemy, game=self.game) or 0)
                        if threshold > 0:
                            overwatch_threshold = int(threshold)
                except Exception:
                    overwatch_threshold = 6
                try:
                    setattr(shooter_unit, "_overwatch_sixes_only", True)
                    setattr(shooter_unit, "_overwatch_hit_threshold", int(overwatch_threshold))
                except Exception:
                    pass
                self._overwatch_flow_active = True

                def _done_callback(executed: bool):
                    try:
                        delattr(shooter_unit, "_overwatch_sixes_only")
                    except Exception:
                        pass
                    try:
                        delattr(shooter_unit, "_overwatch_hit_threshold")
                    except Exception:
                        pass
                    self._overwatch_flow_active = False
                    if executed:
                        s = manager.get_by_name(str(name)) if manager else None
                        if s is None:
                            logger.info("Overwatch: stratagem not found")
                            return
                        apply_info = {}
                        eff_cost = s.cp_cost
                        if hasattr(player, "apply_stratagem_cp_cost"):
                            apply_info = player.apply_stratagem_cp_cost(s, target_unit=shooter_unit) or {}
                            if apply_info.get("denied"):
                                logger.info(f"Overwatch: {apply_info.get('reason', 'not allowed')}")
                                return
                            eff_cost = int(apply_info.get("cost", s.cp_cost))
                        if overwatch_used and not apply_info.get("traitor_enforcer_overwatch_use", False) and not apply_info.get("eye_of_the_augurium_use", False):
                            logger.info("Overwatch: already used this turn")
                            return
                        if player.spend_command_points(
                            eff_cost,
                            reason=f"Stratagem: {s.name}",
                            source="stratagem",
                        ):
                            manager._used_this_turn["OVERWATCH"] = True
                            try:
                                manager._used_stratagems_this_phase.add((s.name or "").strip().upper())
                            except Exception:
                                pass
                            if ctx.get("dequeue") is True and hasattr(manager, "_dequeue_reaction_by_name"):
                                manager._dequeue_reaction_by_name(s.name)
                            if apply_info.get("traitor_enforcer_overwatch_use", False):
                                try:
                                    shooter_unit.mark_traitor_enforcer_overwatch_used(
                                        self.game,
                                        source=str(apply_info.get("traitor_enforcer_overwatch_source", "") or ""),
                                    )
                                except Exception:
                                    pass
                                try:
                                    ability_name = str(
                                        apply_info.get("traitor_enforcer_overwatch_source", "") or "Brutal Example"
                                    ).strip()
                                    leader_id = ""
                                    try:
                                        rule = shooter_unit.get_traitor_enforcer_overwatch_rule() or {}
                                        leader_id = str(rule.get("leader_id", "") or "")
                                    except Exception:
                                        leader_id = ""
                                    if self.game is not None:
                                        self.game.queue_bodyguard_loss(
                                            leader_unit=None,
                                            bodyguard_unit=shooter_unit.get_attached_unit_root(),
                                            ability_name=ability_name or "Brutal Example",
                                            player=player,
                                            leader_unit_id=leader_id,
                                        )
                                except Exception:
                                    pass
                            if apply_info.get("shriekworm_familiar_overwatch_use", False):
                                try:
                                    shooter_unit.mark_shriekworm_familiar_used(
                                        self.game,
                                        source=str(apply_info.get("shriekworm_familiar_overwatch_source", "") or ""),
                                        stratagem_name=str(getattr(s, "name", "") or ""),
                                    )
                                except Exception:
                                    pass
                            logger.info(f"Used stratagem: {name}")
                        else:
                            logger.error("Overwatch: failed to spend CP")
                    else:
                        logger.error("Overwatch cancelled or failed")

                self._request_overwatch_shooting(shooter_unit, enemy, _done_callback)
                return

            ok = manager.use(name, **ctx)
            if ok:
                logger.info(f"Used stratagem: {name}")
            else:
                logger.info(f"Could not use stratagem: {name}")

        if can_traitor:
            if self._optional_flow_active:
                return
            self._optional_flow_active = True
            from ..engine.decision_kinds import DECISION_CONFIRM_YES_NO
            from ..engine.decisions import DecisionOption, DecisionRequest
            ability_name = "Brutal Example"
            try:
                rule = shooter_unit.get_traitor_enforcer_overwatch_rule() or {}
                ability_name = str(rule.get("source", "") or ability_name).strip() or ability_name
            except Exception:
                ability_name = "Brutal Example"
            unit_id = get_entity_id(shooter_unit.get_attached_unit_root())
            message = (
                f"Use {ability_name} to target this unit with Fire Overwatch for 0CP?\n"
                "Each use destroys 1 Bodyguard model."
            )
            ctx_decision = {
                "ability": "brutal_example_overwatch",
                "ability_name": ability_name,
                "message": message,
                "stratagem": str(name),
                "target_unit_id": unit_id,
            }
            options = [
                DecisionOption.create("Use", payload={"choice": True}),
                DecisionOption.create("Skip", payload={"choice": False}),
            ]
            req = _require_pending_decision_request(self.game if self.game is not None else None,
                DECISION_CONFIRM_YES_NO,
                ability_name or "Brutal Example",
                player_id=getattr(player, "id", None),
                options=options,
                context=ctx_decision,

            )

            def _on_resolved(_req, _result):
                chosen = False
                selected = None
                for opt in list(getattr(_req, "options", []) or []):
                    if getattr(opt, "option_id", None) == getattr(_result, "option_id", None):
                        selected = opt
                        break
                payload = dict(getattr(selected, "payload", {}) or {}) if selected is not None else {}
                if "choice" in payload:
                    chosen = bool(payload.get("choice"))
                elif "choice" in getattr(_result, "payload", {}):
                    chosen = bool(_result.payload.get("choice"))
                self._optional_flow_active = False
                _continue_overwatch(chosen)

            if getattr(self, "phase_manager", None) is not None:
                self.phase_manager._register_decision_callback(req, _on_resolved)
            else:
                self._optional_flow_active = False
            return

        if can_eye and overwatch_used:
            if self._optional_flow_active:
                return
            self._optional_flow_active = True
            from ..engine.decision_kinds import DECISION_CONFIRM_YES_NO
            from ..engine.decisions import DecisionOption, DecisionRequest

            ability_name = "Eye of the Augurium"
            try:
                eye_rule = shooter_unit.get_eye_of_the_augurium_stratagem_rule() or {}
                ability_name = str(eye_rule.get("source", "") or ability_name).strip() or ability_name
            except Exception:
                ability_name = "Eye of the Augurium"
            unit_id = get_entity_id(shooter_unit.get_attached_unit_root())
            message = f"Use {ability_name} to target this unit with Fire Overwatch for 0CP?"
            ctx_decision = {
                "ability": "eye_of_the_augurium_stratagem_discount",
                "ability_name": ability_name,
                "message": message,
                "stratagem": str(name),
                "target_unit_id": unit_id,
            }
            options = [
                DecisionOption.create("Use", payload={"choice": True}),
                DecisionOption.create("Skip", payload={"choice": False}),
            ]
            req = _require_pending_decision_request(self.game if self.game is not None else None,
                DECISION_CONFIRM_YES_NO,
                ability_name or "Eye of the Augurium",
                player_id=getattr(player, "id", None),
                options=options,
                context=ctx_decision,

            )

            def _on_eye_resolved(_req, _result):
                chosen = False
                selected = None
                for opt in list(getattr(_req, "options", []) or []):
                    if getattr(opt, "option_id", None) == getattr(_result, "option_id", None):
                        selected = opt
                        break
                payload = dict(getattr(selected, "payload", {}) or {}) if selected is not None else {}
                if "choice" in payload:
                    chosen = bool(payload.get("choice"))
                elif "choice" in getattr(_result, "payload", {}):
                    chosen = bool(_result.payload.get("choice"))
                self._optional_flow_active = False
                _continue_overwatch(False, chosen)

            if getattr(self, "phase_manager", None) is not None:
                self.phase_manager._register_decision_callback(req, _on_eye_resolved)
            else:
                self._optional_flow_active = False
            return

        _continue_overwatch(False, False)

    def _finalize_heroic_intervention(self, player, name: str, context: Dict[str, Any], unit) -> None:
        if self._heroic_flow_active:
            return
        manager = getattr(player, "stratagems", None)
        if manager is None:
            return
        if unit is None:
            logger.info("Heroic Intervention: no unit selected")
            return
        enemy_unit = context.get("enemy_unit")
        if enemy_unit is None:
            logger.info("Heroic Intervention: no enemy unit context")
            return

        dist = None
        try:
            if self.game and getattr(self.game, "map", None):
                dist = self.game.map.get_distance_between_units(unit, enemy_unit)
        except Exception:
            dist = None
        if dist is None or dist > 6.0:
            logger.info("Heroic Intervention: unit not within 6\" of enemy")
            return

        try:
            if unit.has_keyword("Vehicle") and not unit.has_keyword("Walker"):
                logger.info("Heroic Intervention: only WALKER vehicles can be selected")
                return
        except Exception:
            pass

        try:
            from ..rules.stratagems import _unit_cannot_be_target_of_stratagem
            if _unit_cannot_be_target_of_stratagem(unit):
                logger.info("Heroic Intervention: unit cannot be targeted by stratagems")
                return
        except Exception:
            pass

        try:
            if not unit.can_declare_charge_against(enemy_unit, self.game, out_of_turn=True):
                logger.info("Heroic Intervention: unit cannot declare a charge against that enemy")
                return
        except Exception:
            logger.info("Heroic Intervention: unit cannot declare a charge against that enemy")
            return

        cmd_result = None
        try:
            from ..engine.decision_kinds import DECISION_DECLARE_CHARGE
            from ..engine.decisions import DecisionOption, DecisionRequest
            from ..engine.command_kinds import CMD_RESOLVE_DECISION
            from ..engine.commands import GameCommand
            from ..utility.entity_ids import get_entity_id

            unit_id = get_entity_id(unit)
            enemy_id = get_entity_id(enemy_unit)
            req = _require_pending_decision_request(self.game if self.game is not None else None,
                DECISION_DECLARE_CHARGE,
                f"Heroic Intervention: {getattr(unit, 'name', 'Unit')} declares a charge",
                player_id=getattr(player, "id", None),
                options=[
                    DecisionOption.create(
                        getattr(enemy_unit, "name", "Target"),
                        payload={"unit_id": unit_id, "target_unit_id": enemy_id, "out_of_turn": True},
                    )
                ],
                context={"unit_id": unit_id, "out_of_turn": True},

            )
            payload = {
                "decision_id": req.decision_id,
                "option_id": req.options[0].option_id if req.options else "",
                "result_payload": {"target_unit_ids": [enemy_id]},
            }
            cmd = GameCommand.create(CMD_RESOLVE_DECISION, player_id=req.player_id, payload=payload)
            cmd_result = self.game.apply_command(cmd)
        except Exception:
            cmd_result = None
        if cmd_result is None or not getattr(cmd_result, "ok", False):
            logger.error("Heroic Intervention: charge declaration failed")
            return

        name_u = str(name).strip().upper()
        if name_u == "HEROIC INTERVENTION" and name_u in getattr(manager, "_used_stratagems_this_phase", set()):
            try:
                if not manager._heroic_intervention_repeat_allowed(target_unit=unit):
                    logger.info("Heroic Intervention: already used this phase")
                    return
            except Exception:
                logger.info("Heroic Intervention: already used this phase")
                return

        strat = manager.get_by_name(str(name)) if manager else None
        eff_cost = None
        if strat is not None:
            eff_cost = strat.cp_cost
            try:
                if hasattr(player, "apply_stratagem_cp_cost"):
                    eff_cost = int(player.apply_stratagem_cp_cost(strat, target_unit=unit).get("cost", strat.cp_cost))
            except Exception:
                eff_cost = strat.cp_cost
        if strat is None or not player.spend_command_points(
            int(eff_cost or 0),
            reason=f"Stratagem: {strat.name}",
            source="stratagem",
        ):
            logger.error("Heroic Intervention: failed to spend CP")
            return

        if context.get("dequeue") is True and hasattr(manager, "_dequeue_reaction_by_name"):
            manager._dequeue_reaction_by_name(strat.name)
        try:
            manager._used_stratagems_this_phase.add((strat.name or "").strip().upper())
            manager._record_heroic_intervention_use(unit)
        except Exception:
            pass

        self._heroic_flow_active = True

        def on_charge_complete(completed: bool, success: bool, _unit, _targets):
            self._heroic_flow_active = False
            if completed:
                if success:
                    logger.info(f"{unit.name} Heroic Intervention charge successful - achieved engagement range")
                else:
                    logger.error(f"{unit.name} Heroic Intervention charge failed - did not achieve engagement range")
            else:
                logger.error(f"{unit.name} Heroic Intervention charge movement failed or skipped")

        try:
            if self.phase_manager is not None:
                self.phase_manager._queue_pending_charge(
                    unit,
                    [enemy_unit],
                    suppress_charge_bonus=False,
                    on_complete=on_charge_complete,
                )
                if getattr(unit.round_state, "charge_roll", 0):
                    from ..utility.entity_ids import get_entity_id
                    self.phase_manager._handle_charge_roll_ready(unit, [get_entity_id(enemy_unit)])
        except Exception:
            self._heroic_flow_active = False
            logger.exception("Heroic Intervention: failed to queue charge movement")
            return

        logger.info(f"Used stratagem: {name}")

